package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Record each saved setting in the audit file, a line per setting the save sets. */
public class AuditSettingChanged {
    public void audit(@Val SettingsInput input, @Val Settings settings, Audit audit) {
        if (input.setsClerkLimit()) {
            audit.record("SETTING_CHANGED sheet=" + settings.sheetId() + " by=" + input.user()
                    + " key=clerk-limit value=" + SettingsResponse.text(settings.clerkLimit()));
        }
        if (input.floor() != null) {
            audit.record("SETTING_CHANGED sheet=" + settings.sheetId() + " by=" + input.user()
                    + " key=floor value=" + SettingsResponse.text(settings.floor()));
        }
        if (input.terms() != null) {
            audit.record("SETTING_CHANGED sheet=" + settings.sheetId() + " by=" + input.user()
                    + " key=terms value=" + settings.terms());
        }
        input.gradeTerms().forEach((grade, days) -> audit.record("SETTING_CHANGED sheet=" + settings.sheetId()
                + " by=" + input.user() + " key=terms-" + grade + " value=" + (days != null ? days : "")));
        if (input.latePct() != null) {
            audit.record("SETTING_CHANGED sheet=" + settings.sheetId() + " by=" + input.user()
                    + " key=late-pct value=" + SettingsResponse.text(settings.latePct()));
        }
        if (input.setsPolicyDate()) {
            audit.record("SETTING_CHANGED sheet=" + settings.sheetId() + " by=" + input.user()
                    + " key=policy-date value=" + (settings.policyDate() != null ? settings.policyDate() : ""));
        }
        if (input.setsPeriodNumberingFrom()) {
            audit.record("SETTING_CHANGED sheet=" + settings.sheetId() + " by=" + input.user()
                    + " key=period-numbering-from value="
                    + (settings.periodNumberingFrom() != null ? settings.periodNumberingFrom() : ""));
        }
        if (input.setsCap()) {
            audit.record("SETTING_CHANGED sheet=" + settings.sheetId() + " by=" + input.user()
                    + " key=cap value=" + SettingsResponse.text(settings.cap()));
        }
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidSetting {
    public void handle(@Parameter InvalidSettingException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
package net.officefloor.hq.app.setting;

/** A settings save with a clerk limit that is not an amount with two decimals, or no signed-in user. */
public class InvalidSettingException extends Exception {
    public InvalidSettingException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** The sheet's settings as they are now. */
public class RespondWithSettings {
    public void respond(@PathVariable("sheetId") String sheetId, SettingRepository repository,
            ObjectResponse<SettingsResponse> response) {
        response.send(SettingsResponse.from(repository.of(sheetId.trim())));
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveSettings {
    public void save(@PathVariable("sheetId") String sheetId, @Val SettingsInput input, SettingRepository repository,
            Out<Settings> settings) {
        if (input.setsClerkLimit()) {
            repository.setClerkLimit(sheetId.trim(), input.clerkLimit());
        }
        if (input.floor() != null) {
            repository.setFloor(sheetId.trim(), input.floor());
        }
        if (input.terms() != null) {
            repository.setTerms(sheetId.trim(), input.terms());
        }
        input.gradeTerms().forEach((grade, days) -> repository.setGradeTerms(sheetId.trim(), grade, days));
        if (input.latePct() != null) {
            repository.setLatePct(sheetId.trim(), input.latePct());
        }
        if (input.setsPolicyDate()) {
            repository.setPolicyDate(sheetId.trim(), input.policyDate());
        }
        if (input.setsPeriodNumberingFrom()) {
            repository.setPeriodNumberingFrom(sheetId.trim(), input.periodNumberingFrom());
        }
        if (input.setsCap()) {
            repository.setCap(sheetId.trim(), input.cap());
        }
        settings.set(repository.of(sheetId.trim()));
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The sheet's settings, kept on the sheet's row. */
@Repository
public class SettingRepository {

    /** The floor of a sheet that has none stored yet. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** The terms of a sheet that has none stored yet. */
    public static final int DEFAULT_TERMS = 14;

    /** The late percent of a sheet that has none stored yet. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    private final JdbcTemplate jdbc;

    public SettingRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's settings as they are now. */
    public Settings of(String sheetId) {
        return new Settings(sheetId, clerkLimit(sheetId), floor(sheetId), terms(sheetId), latePct(sheetId),
                policyDate(sheetId), periodNumberingFrom(sheetId), gradeTerms(sheetId), cap(sheetId));
    }

    /** The sheet's clerk limit: two decimals, or null when there is none. */
    public BigDecimal clerkLimit(String sheetId) {
        return jdbc.query("SELECT clerk_limit FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getBigDecimal(1) : null, sheetId);
    }

    public void setClerkLimit(String sheetId, BigDecimal limit) {
        jdbc.update("UPDATE sheet SET clerk_limit = ? WHERE id = ?", limit, sheetId);
    }

    /** The sheet's cap: two decimals, or null when there is none; a person's due-total is at most it. */
    public BigDecimal cap(String sheetId) {
        return jdbc.query("SELECT due_cap FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getBigDecimal(1) : null, sheetId);
    }

    public void setCap(String sheetId, BigDecimal cap) {
        jdbc.update("UPDATE sheet SET due_cap = ? WHERE id = ?", cap, sheetId);
    }

    /** The sheet's floor: two decimals; a claim's live due is at least it. */
    public BigDecimal floor(String sheetId) {
        BigDecimal floor = jdbc.query("SELECT due_floor FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getBigDecimal(1) : null, sheetId);
        return floor != null ? floor.setScale(2) : DEFAULT_FLOOR;
    }

    /** The sheet's terms in days: a claim's due-by is its date plus them. */
    public int terms(String sheetId) {
        Integer terms = jdbc.query("SELECT terms_days FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getInt(1) : null, sheetId);
        return terms != null ? terms : DEFAULT_TERMS;
    }

    public void setTerms(String sheetId, int terms) {
        jdbc.update("UPDATE sheet SET terms_days = ? WHERE id = ?", terms, sheetId);
    }

    /** The grades' own terms in days, by grade (A, B, C order); a grade without its own uses the sheet's terms. */
    public Map<String, Integer> gradeTerms(String sheetId) {
        Map<String, Integer> terms = new LinkedHashMap<>();
        jdbc.query("SELECT grade, terms_days FROM grade_terms WHERE sheet_id = ? ORDER BY grade",
                rs -> {
                    terms.put(rs.getString(1), rs.getInt(2));
                }, sheetId);
        return terms;
    }

    /** The terms in days a claim of the grade gets: the grade's own, else the sheet's. */
    public int termsFor(String sheetId, String grade) {
        Integer terms = jdbc.query("SELECT terms_days FROM grade_terms WHERE sheet_id = ? AND grade = ?",
                rs -> rs.next() ? rs.getInt(1) : null, sheetId, grade);
        return terms != null ? terms : terms(sheetId);
    }

    /** Give the grade terms of its own (null: none, it uses the sheet's terms). */
    public void setGradeTerms(String sheetId, String grade, Integer terms) {
        jdbc.update("DELETE FROM grade_terms WHERE sheet_id = ? AND grade = ?", sheetId, grade);
        if (terms != null) {
            jdbc.update("INSERT INTO grade_terms (sheet_id, grade, terms_days) VALUES (?, ?, ?)", sheetId, grade, terms);
        }
    }

    /** The sheet's late percent: two decimals; an overdue claim gains it, of its figure, every full 30 days. */
    public BigDecimal latePct(String sheetId) {
        BigDecimal pct = jdbc.query("SELECT late_pct FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getBigDecimal(1) : null, sheetId);
        return pct != null ? pct.setScale(2) : DEFAULT_LATE_PCT;
    }

    public void setLatePct(String sheetId, BigDecimal pct) {
        jdbc.update("UPDATE sheet SET late_pct = ? WHERE id = ?", pct, sheetId);
    }

    /** The sheet's policy date: null when blank (the sheet's today is the policy date then). */
    public LocalDate policyDate(String sheetId) {
        return jdbc.query("SELECT policy_date FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId);
    }

    public void setPolicyDate(String sheetId, LocalDate date) {
        jdbc.update("UPDATE sheet SET policy_date = ? WHERE id = ?", date, sheetId);
    }

    /** The sheet's period numbering from: null when blank (off). */
    public LocalDate periodNumberingFrom(String sheetId) {
        return jdbc.query("SELECT period_numbering_from FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId);
    }

    public void setPeriodNumberingFrom(String sheetId, LocalDate date) {
        jdbc.update("UPDATE sheet SET period_numbering_from = ? WHERE id = ?", date, sheetId);
    }

    public void setFloor(String sheetId, BigDecimal floor) {
        jdbc.update("UPDATE sheet SET due_floor = ? WHERE id = ?", floor, sheetId);
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Map;

/** A validated settings save: who is making it, and the settings it changes, in order — whether it sets the clerk
 *  limit and to what (two decimals; null: no limit), and the floor it sets (two decimals; null: left as it is) and the terms it sets (days; null: left as it is) and the late percent it sets (two decimals; null: left as it is), and whether it sets the policy date and to what (null: blank, the sheet's today), and whether it sets the period numbering from and to what (null: blank, off), and the grades whose own terms it sets
 *  (A, B, C order) and to what (days; null: none, the sheet's terms), and whether it sets the cap and to what (two
 *  decimals; null: none). */
public record SettingsInput(String user, boolean setsClerkLimit, BigDecimal clerkLimit, BigDecimal floor,
        Integer terms, BigDecimal latePct, boolean setsPolicyDate, LocalDate policyDate,
        boolean setsPeriodNumberingFrom, LocalDate periodNumberingFrom,
        Map<String, Integer> gradeTerms, boolean setsCap, BigDecimal cap) {
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Map;

/** A sheet's settings: the clerk limit (two decimals; null: no limit) the floor (two decimals) and the terms
 *  (days; a claim's due-by is its date plus them) and the late percent (two decimals) and the policy date (null: the sheet's today; a claim dated before it rounds
 *  half up, on or after it half to even) and the period numbering from (null: off; on or after it, by the sheet's today, a claim opened
 *  is numbered within its period) and the grades' own terms (days, by grade; a grade without its own uses the sheet's
 *  terms) and the cap (two decimals; null: none; a person's due-total is at most it). */
public record Settings(String sheetId, BigDecimal clerkLimit, BigDecimal floor, int terms, BigDecimal latePct,
        LocalDate policyDate, LocalDate periodNumberingFrom, Map<String, Integer> gradeTerms, BigDecimal cap) {
}
package net.officefloor.hq.app.setting;

import java.util.Map;

/** Body of a settings save: who is making it and the settings it changes — the clerk limit (blank: no limit) and
 *  the floor and the terms (days) and the late percent and the policy date (yyyy-mm-dd; blank: the sheet's today) and the period numbering from (yyyy-mm-dd; blank: off) and grades' own terms (days by grade;
 *  blank: none, the sheet's terms) and the cap (blank: none); one left out (null) is left as it is. */
public record SettingsRequest(String user, String clerkLimit, String floor, String terms, String latePct,
        String policyDate, String periodNumberingFrom, Map<String, String> gradeTerms, String cap) {
}
package net.officefloor.hq.app.setting;

import java.util.LinkedHashMap;
import java.util.Map;

/** The settings as the screen shows them: the clerk limit with two decimals ('' when there is none) and the floor
 *  with two decimals and the terms in days and the late percent with two decimals and the policy date (yyyy-mm-dd; '' when blank) and the period numbering from (yyyy-mm-dd; '' when off) and each grade's own
 *  terms in days ('' when it has none: it uses the sheet's terms) and the cap with two decimals ('' when there is none). */
public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct,
        String policyDate, String periodNumberingFrom, Map<String, String> gradeTerms, String cap) {
    public static SettingsResponse from(Settings s) {
        return new SettingsResponse(SettingsResponse.text(s.clerkLimit()), SettingsResponse.text(s.floor()),
                String.valueOf(s.terms()), SettingsResponse.text(s.latePct()),
                s.policyDate() != null ? s.policyDate().toString() : "",
                s.periodNumberingFrom() != null ? s.periodNumberingFrom().toString() : "", gradeTerms(s),
                SettingsResponse.text(s.cap()));
    }

    private static Map<String, String> gradeTerms(Settings s) {
        Map<String, String> terms = new LinkedHashMap<>();
        for (String grade : ValidateSettings.GRADES) {
            Integer days = s.gradeTerms().get(grade);
            terms.put(grade, days != null ? String.valueOf(days) : "");
        }
        return terms;
    }

    static String text(java.math.BigDecimal limit) {
        return limit != null ? limit.toPlainString() : "";
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: a signed-in user, a clerk limit (when given)
 *  that is blank (no limit) or an amount 0.00 or more with up to two decimals, and a floor (when given) that is an
 *  amount 0.00 or more with up to two decimals, and terms (when given) that
 *  are a whole number of days, and a late percent (when given) that is a percent 0.00 or more with up to two decimals, and a policy date (when given) that is
 *  blank (the sheet's today) or a date yyyy-mm-dd, and a period numbering from (when given) that is blank (off) or a date yyyy-mm-dd, and grades' own terms (when given)
 *  only for grades A, B or C, and a cap (when given) that is blank (none) or an amount 0.00 or more with up to two decimals, each blank (none: the sheet's terms) or a whole number of days. */
public class ValidateSettings {
    /** The grades that may have terms of their own. */
    static final List<String> GRADES = List.of("A", "B", "C");

    private static final String PERCENT = "\\d{1,3}(\\.\\d{1,2})?";
    private static final String AMOUNT = "\\d{1,12}(\\.\\d{1,2})?";

    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> body) throws InvalidSettingException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidSettingException("Sign in before changing settings.");
        }
        String limit = request.clerkLimit() == null ? null : request.clerkLimit().trim();
        if (limit != null && !limit.isEmpty() && !limit.matches(AMOUNT)) {
            throw new InvalidSettingException("The clerk limit must be an amount, 0.00 or more, with up to two decimals, or blank for no limit.");
        }
        String floor = request.floor() == null ? null : request.floor().trim();
        if (floor != null && !floor.matches(AMOUNT)) {
            throw new InvalidSettingException("The floor must be an amount, 0.00 or more, with up to two decimals.");
        }
        String terms = request.terms() == null ? null : request.terms().trim();
        if (terms != null && !terms.matches("\\d{1,4}")) {
            throw new InvalidSettingException("The terms must be a whole number of days, 0 or more.");
        }
        String latePct = request.latePct() == null ? null : request.latePct().trim();
        if (latePct != null && !latePct.matches(PERCENT)) {
            throw new InvalidSettingException("The late percent must be a percent, 0.00 or more, with up to two decimals.");
        }
        String policy = request.policyDate() == null ? null : request.policyDate().trim();
        LocalDate policyDate = null;
        if (policy != null && !policy.isEmpty()) {
            try {
                policyDate = LocalDate.parse(policy);
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("The policy date must be a date, yyyy-mm-dd, or blank for the sheet's today.");
            }
        }
        String numbering = request.periodNumberingFrom() == null ? null : request.periodNumberingFrom().trim();
        LocalDate numberingFrom = null;
        if (numbering != null && !numbering.isEmpty()) {
            try {
                numberingFrom = LocalDate.parse(numbering);
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("The period numbering from must be a date, yyyy-mm-dd, or blank for off.");
            }
        }
        String cap = request.cap() == null ? null : request.cap().trim();
        if (cap != null && !cap.isEmpty() && !cap.matches(AMOUNT)) {
            throw new InvalidSettingException("The cap must be an amount, 0.00 or more, with up to two decimals, or blank for none.");
        }
        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
        if (request.gradeTerms() != null) {
            for (String grade : request.gradeTerms().keySet()) {
                if (!GRADES.contains(grade)) {
                    throw new InvalidSettingException("Terms may be set only for grade A, B or C.");
                }
            }
            for (String grade : GRADES) {
                if (!request.gradeTerms().containsKey(grade)) {
                    continue;
                }
                String days = request.gradeTerms().get(grade) == null ? "" : request.gradeTerms().get(grade).trim();
                if (!days.isEmpty() && !days.matches("\\d{1,4}")) {
                    throw new InvalidSettingException("The terms of grade " + grade
                            + " must be a whole number of days, 0 or more, or blank for the sheet's terms.");
                }
                gradeTerms.put(grade, days.isEmpty() ? null : Integer.valueOf(days));
            }
        }
        body.set(new SettingsInput(request.user().trim(), limit != null,
                limit == null || limit.isEmpty() ? null : new BigDecimal(limit).setScale(2),
                floor == null ? null : new BigDecimal(floor).setScale(2),
                terms == null ? null : Integer.valueOf(terms),
                latePct == null ? null : new BigDecimal(latePct).setScale(2),
                policy != null, policyDate, numbering != null, numberingFrom, gradeTerms,
                cap != null, cap == null || cap.isEmpty() ? null : new BigDecimal(cap).setScale(2)));
    }
}
