package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Grades;
import net.officefloor.hq.app.person.Holds;
import net.officefloor.hq.app.rate.RateRepository;

/** Claim figures and due-totals, as the screen shows them. */
public final class Dues {
    private Dues() {
    }

    /** A claim's figure: the due fixed when it was settled, else the one its last statement bound it to, n/a
     *  included (not while it is PENDING: then it is live), else
     *  live: its amount times its person's rate in force on its date for their grade then, divided by 100, rounded to two
     *  decimals as the claim rounds (see Rounding), and at least the sheet's floor; null (n/a) when no rate applies. */
    public static BigDecimal figure(Claim claim, Grades grades, RateRepository rates, BigDecimal floor,
            Rounding rounding) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
            return claim.statedDue();
        }
        return live(claim, grades, rates, floor, rounding);
    }

    /** A claim's due as its row shows it: the due fixed when it was settled, else its figure (bound or live) with
     *  the late charge on it added on top; null (n/a) when it has no figure. */
    public static BigDecimal shown(Claim claim, Grades grades, RateRepository rates, BigDecimal floor,
            LateCharge late) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        BigDecimal figure = figure(claim, grades, rates, floor, late.rounding());
        return figure != null ? figure.add(late.on(claim, figure)) : null;
    }

    /** A claim's live due: its amount times its person's rate in force on its date for their grade then, divided by 100, rounded
     *  to two decimals as the claim rounds (see Rounding), raised to the floor when below it (a correction, a negative amount, has no floor); null (n/a) when no rate applies. */
    public static BigDecimal live(Claim claim, Grades grades, RateRepository rates, BigDecimal floor,
            Rounding rounding) {
        return rates.on(claim.sheetId(), grades.on(claim.date()), claim.date())
                .map(r -> claim.amount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, rounding.of(claim)))
                .map(due -> claim.amount().signum() < 0 ? due : due.max(floor))
                .orElse(null);
    }

    /** Whether a claim counts toward its person's figures and every live total: an OPEN, PENDING or SETTLED one,
     *  except an OPEN one dated within one of its person's holds and not bound by a statement. */
    public static boolean counts(Claim claim, Holds holds) {
        return claim.status().counts()
                && !(claim.status() == ClaimStatus.OPEN && !claim.stated() && holds.covers(claim.date()));
    }

    /** A person's due-total: the dues (as shown) of their claims that count added up, skipping n/a; null (n/a) when
     *  their grade today has no rate today, unless a claim that counts has a figure (settled, stated, or live at
     *  the grade in force on its date). */
    public static BigDecimal total(String sheetId, List<Claim> claims, Grades grades, Holds holds, LocalDate today,
            RateRepository rates, BigDecimal floor, LateCharge late) {
        List<Claim> counted = claims.stream().filter(c -> counts(c, holds)).toList();
        List<BigDecimal> figures = counted.stream().map(c -> shown(c, grades, rates, floor, late))
                .filter(f -> f != null).toList();
        if (figures.isEmpty() && rates.on(sheetId, grades.on(today), today).isEmpty()) {
            return null;
        }
        return figures.stream().reduce(new BigDecimal("0.00"), BigDecimal::add);
    }

    /** A due-total at most the sheet's cap (null: none); n/a (null) is not capped. */
    public static BigDecimal capped(BigDecimal total, BigDecimal cap) {
        return total != null && cap != null ? total.min(cap) : total;
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/** The sheet's late charge as it is today: its late percent (a claim is overdue past its own due-by, fixed when
 *  it was created) and its today (null: none, so nothing is overdue). */
public record LateCharge(BigDecimal pct, LocalDate today, Rounding rounding) {

    /** The sheet's late charge as it is now. */
    public static LateCharge of(String sheetId, SettingRepository settings, SheetRepository sheets,
            ClaimRepository claims) {
        return new LateCharge(settings.latePct(sheetId), sheets.today(sheetId),
                Rounding.of(sheetId, settings, sheets, claims));
    }

    /** No late charge at all. */
    public static LateCharge none() {
        return new LateCharge(BigDecimal.ZERO, null, Rounding.none());
    }

    /** Whether a claim is overdue: it is OPEN or PENDING and its due-by is before today. */
    public boolean overdue(Claim claim) {
        return claim.status().unsettled() && today != null
                && claim.dueBy().isBefore(today);
    }

    /** The charge on a claim whose figure is `figure`: the late percent of the figure for every full 30 days it
     *  is overdue, rounded to two decimals as the claim rounds (see Rounding); 0.00 when it is not overdue, or it is a correction (a negative amount). */
    public BigDecimal on(Claim claim, BigDecimal figure) {
        if (!overdue(claim) || pct.signum() == 0 || claim.amount().signum() < 0) {
            return new BigDecimal("0.00");
        }
        long periods = ChronoUnit.DAYS.between(claim.dueBy(), today) / 30;
        return figure.multiply(pct).multiply(BigDecimal.valueOf(periods))
                .divide(BigDecimal.valueOf(100), 2, rounding.of(claim));
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.statement.Dues;
import net.officefloor.hq.app.statement.LateCharge;
import org.springframework.stereotype.Service;

/** Takes the sheet's figures, and records in the audit file how they moved over a change: a ROLLUP line per
 *  person whose figures (claimed, due-total, overdue-total) changed (a person new to the sheet counting as changed), in the order they were added,
 *  then a TOTALS line when the sheet's totals changed. A change that moves no figure records nothing. */
@Service
public class Rollups {

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SettingRepository settings;
    private final Audit audit;

    public Rollups(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SettingRepository settings, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
        this.audit = audit;
    }

    /** The sheet's figures as they are now. */
    public Rollup take(String sheetId) {
        var today = sheets.today(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        BigDecimal cap = settings.cap(sheetId);
        LateCharge late = LateCharge.of(sheetId, settings, sheets, claims);
        List<Claim> all = claims.list(sheetId);
        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = new BigDecimal("0.00");
        BigDecimal dueTotal = new BigDecimal("0.00");
        BigDecimal overdueTotal = new BigDecimal("0.00");
        for (Person p : people.list(sheetId)) {
            List<Claim> theirs = all.stream().filter(c -> c.personId() == p.id()).toList();
            BigDecimal claimed = theirs.stream().filter(c -> Dues.counts(c, p.holds())).map(Claim::amount)
                    .reduce(new BigDecimal("0.00"), BigDecimal::add);
            BigDecimal due = Dues.capped(
                    Dues.total(sheetId, theirs, p.grades(), p.holds(), today, rates, floor, late), cap);
            // overdue-total: the dues (as shown, late charge included) of their overdue claims that count, skipping n/a
            BigDecimal overdue = theirs.stream().filter(c -> Dues.counts(c, p.holds()) && late.overdue(c))
                    .map(c -> Dues.shown(c, p.grades(), rates, floor, late)).filter(Objects::nonNull)
                    .reduce(new BigDecimal("0.00"), BigDecimal::add);
            claimedTotal = claimedTotal.add(claimed);
            overdueTotal = overdueTotal.add(overdue);
            if (due != null) {
                dueTotal = dueTotal.add(due);
            }
            figures.put(p.id(), new Rollup.Figures(p.name(), shown(claimed), due != null ? shown(due) : "n/a",
                    shown(overdue)));
        }
        return new Rollup(figures, shown(claimedTotal), shown(dueTotal), shown(overdueTotal));
    }

    /** Record how the sheet's figures moved since `before`, as a change made by `user`. */
    public void record(String sheetId, String user, Rollup before) {
        Rollup after = take(sheetId);
        for (var e : after.people().entrySet()) {
            Rollup.Figures was = before.people().get(e.getKey());
            Rollup.Figures now = e.getValue();
            if (was == null || !Objects.equals(was.claimed(), now.claimed())
                    || !Objects.equals(was.dueTotal(), now.dueTotal())
                    || !Objects.equals(was.overdueTotal(), now.overdueTotal())) {
                audit.record("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + now.name()
                        + " claimed=" + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
            }
        }
        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())
                || !before.overdueTotal().equals(after.overdueTotal())) {
            audit.record("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
        }
    }

    private static String shown(BigDecimal value) {
        return value.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** Rates by sheet: per grade, at most one per from-date (and at most one with no from-date). */
@Repository
public class RateRepository {

    private static final RowMapper<Rate> ROW = (rs, i) -> new Rate(rs.getString("sheet_id"),
            rs.getString("grade"), rs.getBigDecimal("pct"), rs.getObject("from_date", LocalDate.class),
            rs.getObject("to_date", LocalDate.class));

    private final JdbcTemplate jdbc;

    public RateRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's rates by grade, each grade's earliest first (the one with no from-date before all). */
    public List<Rate> list(String sheetId) {
        return jdbc.query("SELECT * FROM rate WHERE sheet_id = ? ORDER BY grade, from_date NULLS FIRST", ROW, sheetId);
    }

    /** The grade's rate in force on the date: the one whose from-date is the latest on or before it (no
     *  from-date counting as the beginning of time); empty when none applies, or that one's to-date is before the date. */
    public Optional<Rate> on(String sheetId, String grade, LocalDate date) {
        return list(sheetId).stream().filter(r -> r.grade().equals(grade) && r.appliesOn(date))
                .max(Comparator.comparing(Rate::from, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(r -> !r.endedBy(date));
    }

    /** Set the grade's rate from the from-date (null: from the beginning of time) through the to-date (null:
     *  with no end), replacing any it had from that same date. */
    public Rate set(String sheetId, String grade, BigDecimal pct, LocalDate from, LocalDate to) {
        Date fromDate = from != null ? Date.valueOf(from) : null;
        Date toDate = to != null ? Date.valueOf(to) : null;
        jdbc.update("DELETE FROM rate WHERE sheet_id = ? AND grade = ? AND from_date IS NOT DISTINCT FROM ?",
                sheetId, grade, fromDate);
        jdbc.update("INSERT INTO rate (sheet_id, grade, pct, from_date, to_date) VALUES (?, ?, ?, ?, ?)",
                sheetId, grade, pct, fromDate, toDate);
        return new Rate(sheetId, grade, pct, from, to);
    }
}

